PROGRAM EulerProblem4(OUTPUT);

VAR
  a, b, prod, rev, tmp, best: INTEGER32;

BEGIN
  best := 0;
  FOR a := 100 TO 999 DO
    FOR b := a TO 999 DO

reference_continuation:
    BEGIN
      prod := a * b;
      tmp := prod;
      rev := 0;
      WHILE tmp > 0 DO
      BEGIN
        rev := rev * 10 + tmp MOD 10;
        tmp := tmp DIV 10
      END;
      IF (rev = prod) AND (prod > best) THEN
        best := prod
    END;
  WRITELN(best)
END.
